SLO = ("SLO = 0.995                 # сұраулардың 99.5%-ы сәтті және 300 мс ішінде\n"
       "window_requests = 2_000_000 # 30 күндік терезедегі күтілетін сұраулар\n"
       "budget = (1 - SLO) * window_requests\n"
       "print(f'қате бюджеті: {budget:.0f} «нашар» сұрау')\n\n"
       "# күн сайынғы (жақсы, барлық) сұраулар - алғашқы 10 күн\n"
       "days = [(66500, 66700), (66600, 66650), (64000, 66800), (66550, 66600), (66700, 66720),\n"
       "        (66000, 66900), (66600, 66640), (66680, 66700), (65900, 66500), (66610, 66630)]\n"
       "bad = sum(t - g for g, t in days)\n"
       "elapsed = len(days) / 30\n"
       "spent = bad / budget\n"
       "print(f'өтті: {elapsed:.0%} уақыт, жұмсалды: {spent:.0%} бюджет')\n"
       "rate = spent / elapsed\n"
       "print('бюджет терезе соңына дейін', 'жетеді' if rate <= 1 else f'{elapsed / spent * 30:.1f}-күні бітеді')")

