RBD = ("from math import comb\n\n"
       "def series(*a):\n"
       "    p = 1.0\n"
       "    for x in a:\n"
       "        p *= x\n"
       "    return p\n\n"
       "def parallel(*a):\n"
       "    q = 1.0\n"
       "    for x in a:\n"
       "        q *= 1 - x\n"
       "    return 1 - q\n\n"
       "def k_of_n(k, n, a):\n"
       "    \"\"\"n бірдей тәуелсіз дананың кемінде k-сы жұмыс істеуі керек\"\"\"\n"
       "    return sum(comb(n, i) * a ** i * (1 - a) ** (n - i) for i in range(k, n + 1))\n\n"
       "lb, app, db = 0.9999, 0.995, 0.999\n"
       "print('бір данадан:          ', round(series(lb, app, db), 5))\n"
       "print('app × 3 параллель:     ', round(series(lb, parallel(app, app, app), db), 5))\n"
       "print('+ db 3-тен 2 (кворум): ', round(series(lb, parallel(app, app, app), k_of_n(2, 3, db)), 5))")

